/// <summary>
/// Manager class for handling operations on AVARUMCashSalesDesk.
/// </summary>
internal final class AVARUMCashSalesDeskManager
{
    /// <summary>
    /// Key for storing the last value of CashSalesDeskId.
    /// </summary>
    public static str lastValue_CashSalesDeskId_Key = strFmt('%1_%2', classStr(AVARUMCashSalesDeskManager), extendedTypeStr(AVARUMCashSalesDeskId));

    private static AVARUMCashSalesParameters cashSalesParameters = null;
    private AVARUMCashSalesDeskId cashSalesDeskId;
    private AVARUMCashSalesDesk cashSalesDesk;
    private BarcodeSetup barcodeSetup; 
    private Amount givenAmount;
    private static SalesUnit preciseWeightQtyUnit = null;

}

