/// <summary>
/// Main method to handle the state change of the cash sales desk.
/// </summary>
/// <param name="_args">Arguments containing the state and record information.</param>
public static void main(Args _args)
{
    boolean result;

    if (!_args)
    {
        throw Global::error("@AVARUM:ArgumentsNotProvided");
    }
    else if (!_args.record())
    {
        throw Global::error("@AVARUM:RecordNotProvided");
    }

    switch  (_args.parmEnumType())
    {
        case enumNum(AVARUMCashSalesDeskState):
            AVARUMCashSalesDesk cashSalesDesk;
            Args dialogArgs;
            FormRun dialogFormRun;

            if (!_args.record() || !_args.record().TableId == tableNum(AVARUMCashSalesDesk))
            {
                throw Global::error("@AVARUM:RecordOfTypeNotProvided", Global::tableId2Name(tableNum(AVARUMCashSalesDesk)));
            }

            cashSalesDesk = _args.record() as AVARUMCashSalesDesk;

            if (_args.parmEnum()==AVARUMCashSalesDeskState::Closed)
            {
                AVARUMCashSalesDeskManager::checkCanClose(cashSalesDesk);
            }

            dialogArgs = new Args(formStr(AVARUSCashSalesDeskAmountDialog));
            dialogArgs.record(cashSalesDesk);
            dialogArgs.parmEnum(_args.parmEnum());
            dialogArgs.parmEnumType(_args.parmEnumType());

            dialogFormRun = New FormRun(dialogArgs);
            dialogFormRun.init();
            dialogFormRun.run();
            dialogFormRun.wait(true);

            result = !dialogFormRun.closedCancel();

            switch (_args.parmEnum())
            {
                case AVARUMCashSalesDeskState::Open:     
                    /// First create the sales order header for today.
                    result = result && AVARUMCashSalesDeskManager::createSalesOrderHeader(cashSalesDesk);

                    /// If the sales order header is created successfully, then open the cash sales desk.
                    result = result && cashSalesDesk.open();

                    if (!result)
                    {
                        //AVARUMCashSalesDeskManager::deleteSalesOrderHeader(cashSalesDesk);
                        throw Global::warning("@AVARUM:CashSalesDeskOpenCanceled");
                    }
                    break;

                case AVARUMCashSalesDeskState::Closed:                       
                    /// First close the cash sales desk.
                    result = result && cashSalesDesk.close();

                    if (!result)
                    {
                        throw Global::warning("@AVARUM:CashSalesDeskCloseCanceled");
                    }   

                    // If the cash sales desk is closed successfully, then delete the sales order header for today.
                    //AVARUMCashSalesDeskManager::deleteSalesOrderHeader(cashSalesDesk);
                    AVARUMCashSalesDeskManager::closeCashDesk(cashSalesDesk);
                    break;

                default:
                    throw Global::error(strFmt("@AVARUM:NotSupportedEnumValueProvided", enum2Str(_args.parmEnum())));
            }                 
            break;

        case enumNum(AVARUMCashSalesAction):
            //SalesTable salesTable;

            //if (!_args.record().TableId == tableNum(SalesTable))
            //{
            //    throw Global::error("@AVARUM:RecordOfTypeNotProvided", Global::tableId2Name(tableNum(SalesTable)));
            //}

            //salesTable = _args.record() as SalesTable;                
            if (!_args.record() || !_args.record().TableId == tableNum(AVARUMCashSalesDesk))
            {
                throw Global::error("@AVARUM:RecordOfTypeNotProvided", Global::tableId2Name(tableNum(AVARUMCashSalesDesk)));
            }

            cashSalesDesk = _args.record() as AVARUMCashSalesDesk;

            switch (_args.parmEnum())
            {
                case AVARUMCashSalesAction::Post:
                    //result = AVARUMCashSalesDeskManager::postSalesOrder(salesTable);
                    AVARUMCashSalesDeskManager::postCashDesk(cashSalesDesk, _args.parmObject());
                    break;

                default:
                    throw Global::error(strFmt("@AVARUM:NotSupportedEnumValueProvided", enum2Str(_args.parmEnum())));
            }                     
            break;

        default:
            throw Global::error(strFmt("@AVARUM:NotSupportedEnumTypeProvided", enum2Str(_args.parmEnumType())));
    }       

}

/// <summary>
/// Saves the last used CashSalesDeskId.
/// </summary>
/// <param name="_cashSalesDeskId">The CashSalesDeskId to save.</param>
public static void saveLastCashSalesDeskId(AVARUMCashSalesDeskId _cashSalesDeskId)
{
    xSysLastValue::putValue([_cashSalesDeskId], curExt(), curUserId(), UtilElementType::Class, AVARUMCashSalesDeskManager::lastValue_CashSalesDeskId_Key);
}

/// <summary>
/// Retrieves the last used CashSalesDeskId.
/// </summary>
/// <returns>The last used CashSalesDeskId.</returns>
public static AVARUMCashSalesDeskId getLastCashSalesDeskId()
{
    AVARUMCashSalesDeskId cashSalesDeskId;

    container value = xSysLastValue::getValue(curExt(), curUserId(), UtilElementType::Class, AVARUMCashSalesDeskManager::lastValue_CashSalesDeskId_Key);

    if (value != conNull())
    {
        [cashSalesDeskId] = value;
    }

    return cashSalesDeskId;
}

/// <summary>
/// Deletes the last used CashSalesDeskId.
/// </summary>
public static void deleteLastCashSalesDeskId()
{
    xSysLastValue::deleteValue(curExt(), curUserId(), UtilElementType::Class, AVARUMCashSalesDeskManager::lastValue_CashSalesDeskId_Key, AVAConstants::emptyString);
}

/// <summary>
/// Gets the cash sales parameters.
/// </summary>
/// <returns>The cash sales parameters.</returns>
public static AVARUMCashSalesParameters parmCashSalesParameters()
{
    if (AVARUMCashSalesDeskManager::cashSalesParameters == null)
    {
        /// Find the cash sales parameters.
        AVARUMCashSalesParameters parms = AVARUMCashSalesParameters::find();
        AVARUMCashSalesDeskManager::cashSalesParameters = parms;

        /// Set the precise weight quantity unit.
        AVARUMCashSalesDeskManager::preciseWeightQtyUnit = UnitOfMeasure::find(parms.PreciseWeightQtyUnitRefRecId).Symbol;

        /// Subscribe to the hasChanged event of the cash sales parameters table.
        AVARUMCashSalesParameters::hasChanged += eventhandler(AVARUMCashSalesDeskManager::clearStaticData);
    }

    return AVARUMCashSalesDeskManager::cashSalesParameters;
}

/// <summary>
/// Gets the precise weight quantity unit.
/// </summary>
/// <returns>SalesUnit</returns>
public static SalesUnit parmPreciseWeightQtyUnit()
{
    return AVARUMCashSalesDeskManager::preciseWeightQtyUnit;
}

/// <summary>
/// Clears the static data.
/// </summary>
private static void clearStaticData()
{
    /// Clear the static data.
    AVARUMCashSalesDeskManager::cashSalesParameters = null;
    AVARUMCashSalesDeskManager::preciseWeightQtyUnit = null;

    /// Remove the event handler.
    AVARUMCashSalesParameters::hasChanged -= eventhandler(AVARUMCashSalesDeskManager::clearStaticData);
}

/// <summary>
/// Gets the barcode setup.
/// </summary>
/// <returns>The barcode setup.</returns>
public BarcodeSetup parmBarcodeSetup()
{
    if (AVARUMCashSalesDeskManager::parmCashSalesParameters() && !this.barcodeSetup)
    {
        this.barcodeSetup = AVARUMCashSalesDeskManager::parmCashSalesParameters().barcodeSetup();
    }

    return this.barcodeSetup;
}

