/// <summary>
/// Initializes a new instance of the AVARUMCashSalesDeskManager class.
/// </summary>
/// <param name="_cashSalesDeskId">The cash sales desk ID.</param>
private void new(AVARUMCashSalesDeskId _cashSalesDeskId)
{
    this.cashSalesDeskId = _cashSalesDeskId;
    this.parmCashSalesDesk().clear();

    if (this.cashSalesDeskId)
    {
        this.cashSalesDesk = AVARUMCashSalesDesk::find(this.cashSalesDeskId);
    }

    this.parmCashSalesDesk().stateChanged += eventhandler(this.cashDesk_StateChanged);
}

/// <summary>
/// Handles the state change of the cash sales desk.
/// </summary>
/// <param name="_newState">The new state of the cash sales desk.</param>
private void cashDesk_StateChanged(AVARUMCashSalesDeskState _newState)
{
    this.parmCashSalesDesk().State = _newState;
}

