/// <summary>
/// Validates the cash sales desk manager.
/// </summary>
/// <param name="_suppressMessages">Indicates whether to suppress messages.</param>
/// <returns>True if valid, otherwise false.</returns>
public boolean isValid(boolean _suppressMessages = false)
{
    int lastInfoLine;
    var isValid = true;

    // Get the current line number in the infolog.
    lastInfoLine = Global::infologLine();

    isValid = isValid && this.validateDependencies();
    isValid = isValid && this.validateCashSalesDesk(!_suppressMessages);

    // Clear infolog messages if suppression is requested.        
    if (0)//if (_suppressMessages)   
    {
        infolog.clear(lastInfoLine);
    }

    return isValid;
}

/// <summary>
/// Validates the cash sales desk.
/// </summary>
/// <returns>True if valid, otherwise false.</returns>
private boolean validateCashSalesDesk(boolean _doText=true)
{
    var isValid = true;

    if (this.parmCashSalesDesk().RecId == 0)
    {
        isValid =  false;
        if (_doText)
        {
            Global::checkFailed("@AVARUM:CashSalesPleaseSelectADesk");
        }

    }
    else if (!this.parmCashSalesDesk().IsOpen())
    {
        isValid =  false;
        //if (_doText)   // no text
        //{
        //    Global::checkFailed("@AVARUM:CashSalesNoDeskOpen");
        // }
    }
    else if (this.parmCashSalesDesk().isCloseRequired())
    {
        isValid =  false;
        if (_doText)
        {
            Global::checkFailed(strFmt("@AVARUM:CashSalesDeskCloseRequired", this.parmCashSalesDesk().openAtAsDate()));
        }
    }

    return isValid;
}

/// <summary>
/// Validates the dependencies.
/// </summary>
/// <returns>True if valid, otherwise false.</returns>
private boolean validateDependencies()
{
    var isValid = true;

    if (!AVARUMCashSalesDeskManager::parmCashSalesParameters())
    {
        isValid = Global::checkFailed(strFmt("@AVARUM:ParameterNotDefined", "@AVARUM:CashSalesParametersTable")) && isValid;
    }

    if (!AVARUMCashSalesDeskManager::parmCashSalesParameters().Customer || !CustTable::exist(AVARUMCashSalesDeskManager::parmCashSalesParameters().Customer))
    {
        isValid = Global::checkFailed("@AVARUM:CashSalesCustomerNotDefined") && isValid;
    }

    if (!AVARUMCashSalesDeskManager::parmPreciseWeightQtyUnit())
    {
        isValid = Global::checkFailed("@AVARUM:CashSalesPreciseWeightQtyUnitNotDefined") && isValid;
    }

    return isValid;
}

/// <summary>
/// Processes the input scanned by the cash sales desk.
/// </summary>
/// <param name="_salesId">The saes order id.</param>
/// <param name="_input">The input to process.</param>
/// <returns>True if the input is valid, otherwise false.</returns>
public boolean processInput(SalesId _salesId, AVARUMCashSalesInput _input)
{
    boolean result;
    int inputLen;
    int inputMinLen = 13;
    int inputMaxLen = 13;
    boolean isValidBarcode;
    InventItemBarcode itemBarcode;
    ItemId itemId;
    SalesQty salesQty;
    SalesUnit salesUnit;
    InventDimId InventDimId;
    str realStr;

    inputLen = strLen(_input);
    result = true;

    if (inputLen == 0)
    {
        return result;
    }

    isValidBarcode = true;

    if (this.parmBarcodeSetup())
    {
        isValidBarcode = this.parmBarcodeSetup().validateBarcode_AVA(_input, true);

        inputMinLen = this.parmBarcodeSetup().minimumLength > 0 ? this.parmBarcodeSetup().minimumLength : inputMinLen;
        inputMaxLen = this.parmBarcodeSetup().maximumLength > 0 ? this.parmBarcodeSetup().maximumLength : inputMaxLen;
    }

    /// If the input length is between the barcode min and max length, then try to find the item barcode.
    if (isValidBarcode && inputLen >= inputMinLen && inputLen <= inputMaxLen)
    {
        itemBarcode = InventItemBarcode::findBarcode_AVA(_input, AVARUMCashSalesDeskManager::parmCashSalesParameters().BarcodeSetupId);
        itemId = itemBarcode.ItemId;
        InventDimId = itemBarcode.inventDimId;  // Product dimensions
        //salesQty = itemBarcode.AVARUMWeight;
        salesQty = itemBarcode.qty;
        salesUnit = itemBarcode.UnitID;
        if (!salesQty)
        {
            warning("@AVARUM:AVARUMCashSalesDeskManagerMsg2");
        }
    }
    else
    {
        // If not a valid barcode, then try to find the item id from the input string.
        inputMinLen = AVARUMCashSalesDeskManager::parmCashSalesParameters().ItemIdLen;
        inputMaxLen = AVARUMCashSalesDeskManager::parmCashSalesParameters().ItemIdLen + AVARUMCashSalesDeskManager::parmCashSalesParameters().ItemWeightLen;

        if (inputLen >= inputMinLen && inputLen <= inputMaxLen)
        {
            itemId = subStr(_input, 1, AVARUMCashSalesDeskManager::parmCashSalesParameters().ItemIdLen);

            /// Remove the item id length from the input length to get the remaining length.
            int inputRestLen = inputLen - AVARUMCashSalesDeskManager::parmCashSalesParameters().ItemIdLen;

            salesQty = 1;

            /// If the remaining length is equal to the item weight length, then set the sales quantity.
            if (inputRestLen == AVARUMCashSalesDeskManager::parmCashSalesParameters().ItemWeightLen)
            {
                str qtyStr = subStr(_input, AVARUMCashSalesDeskManager::parmCashSalesParameters().ItemIdLen + 1, AVARUMCashSalesDeskManager::parmCashSalesParameters().ItemWeightLen);

                try
                {
                    salesQty = str2num(qtyStr); // / 1000;                                                     
                    salesUnit = AVARUMCashSalesDeskManager::parmPreciseWeightQtyUnit();
                }
                catch
                {
                    salesQty = 1;
                }
            }
        }
        else
        {
            // use as amount
            realStr = strReplace(_input,',','.');
            givenAmount = str2num(realStr);
        }
    }

    /// If the item id is found validate the item if it exists.
    if (itemId)
    {
        // If the item is found, then add the sales order line.
        result = this.addSalesOrderLine(_salesId, itemId, salesQty, salesUnit, inventDimId);
    }

    return result;
}

/// <summary>
/// Returns the amount given
/// </summary>
/// <returns>amount given</returns>
public Amount getGivenAmount()
{
    return givenAmount;
}

/// <summary>
/// Reset fields after posting
/// </summary>
public void resetAfterPost()
{
    givenAmount=0;
}

/// <summary>
/// Creates a sales order header for the given cash sales desk.
/// </summary>
/// <param name="_cashSalesDesk">The cash sales desk record.</param>
/// <returns>True if the sales order header is created successfully, otherwise false.</returns>
private static boolean createSalesOrderHeader(AVARUMCashSalesDesk _cashSalesDesk)
{
    boolean result;
    SalesId salesId;
    SalesOrderHeaderV4Entity salesOrderHeader;

    //salesId = AVARUMCashSalesDeskManager::generateSalesId(_cashSalesDesk.Id);
    //if (SalesTable::exist(salesId))
    //{
        //    return true;
        //}

    try
    {
        ttsbegin;
        salesId = NumberSeq::newGetNum(SalesParameters::numRefSalesId()).num();

        salesOrderHeader.skipNumberSequenceCheck(true);
        salesOrderHeader.initValue();
        salesOrderHeader.SalesOrderNumber = salesId;
        salesOrderHeader.SalesOrderName = strFmt("@AVARUM:AVARUMCashSalesDeskSalesName", date2Str(systemDateGet(), 123, DateDay::Digits2, DateSeparator::Dot, DateMonth::Digits2, DateSeparator::Dot, DateYear::Digits4));
        salesOrderHeader.OrderingCustomerAccountNumber = AVARUMCashSalesDeskManager::parmCashSalesParameters().Customer;            
        salesOrderHeader.insert();

        SalesTable locSalesTable=SalesTable::find(salesId, true);
        locSalesTable.Reservation=ItemReservation::Automatic;
        locSalesTable.PdsBatchAttribAutoRes=NoYes::Yes;
        locSalesTable.update();

        NumberSequenceReference numberSeqReference=NumberSeqReference::findReference(extendedTypeNum(AVARUMCashVoucher));
        NumberSeq NumberSeq=NumberSeq::newGetNum(numberSeqReference);
        AVARUMCashVoucher cashVoucher=NumberSeq.num();
        NumberSeq.used();
        AVARUMCashSalesDesk updAVARUMCashSalesDesk;
        updAVARUMCashSalesDesk=AVARUMCashSalesDesk::findByRecId(_cashSalesDesk.RecId, true);
        updAVARUMCashSalesDesk.CashVoucher=cashVoucher;
        updAVARUMCashSalesDesk.SalesId=salesId;
        updAVARUMCashSalesDesk.Amount=_cashSalesDesk.Amount;
        updAVARUMCashSalesDesk.update();
        ttscommit;

        _cashSalesDesk.reread();

        result = true;
    }
    catch
    {
        result = false;
    }

    return result;
}

/// <summary>
/// Deletes the sales order header for the given cash sales desk.
/// </summary>
/// <param name="_cashSalesDesk">The cash sales desk record.</param>
/// <returns>True if the sales order header is deleted successfully, otherwise false.</returns>
private static boolean deleteSalesOrderHeader(AVARUMCashSalesDesk _cashSalesDesk)
{
    boolean result;
    SalesId salesId;
    SalesTable salesTable;

    //salesId = AVARUMCashSalesDeskManager::generateSalesId(_cashSalesDesk.Id, _cashSalesDesk.openAtAsDate());
    salesId=_cashSalesDesk.SalesId;
    salesTable = SalesTable::find(salesId, true);
    result = true;

    if (salesTable)
    {
        try
        {
            ttsbegin;

            salesTable.delete();

            ttscommit;
        }
        catch
        {
            result = false;
        }
    }

    return result;
}

/// <summary>
/// Ads a sales order line for the given item and quantity to the current sales order of today.
/// </summary>
/// <param name="_salesId">The saes order id.</param>
/// <param name="_itemId">The item ID.</param>
/// <param name="_salesQty">The sales quantity.</param>
/// <param name="_salesUnit">The sales unit id.</param>
/// <param name="_inventDimId">Given product dimensions</param>
/// <returns>True if the sales order line is addedd successfully, otherwise false.</returns>
private boolean addSalesOrderLine(SalesId _salesId, ItemId _itemId, SalesQty _salesQty, SalesUnit _salesUnit, InventDimId _inventDimId)
{
    boolean result; 
    //SalesOrderLineV3Entity salesOrderLine;
    SalesLine salesLine;

    try
    {
        InventTable inventTable = InventTable::find(_itemId);

        if (!inventTable)
        {
            throw Global::error(strFmt("@AVARUM:ItemNotFound", _itemId));
        }

        // Validate that the item is sellable.
        InventItemSalesSetup inventItemSalesSetup = InventItemSalesSetup::findDefault(_itemId);

        if (!inventItemSalesSetup)
        {
            throw Global::error(strFmt("@AVARUM:ItemNotSellable", _itemId));
        }

        if (!_salesId)
        {
            throw Global::error("@AVARUM:SalesOrderNotProvided");

            //AVARUMCashSalesDeskManager::createSalesOrderHeader(this.parmCashSalesDesk());
            //_salesId = AVARUMCashSalesDeskManager::generateSalesId(this.parmCashSalesDesk().Id);            

            //if (!_salesId)
            //{
            //    throw Global::error("@AVARUM:SalesOrderNotProvided");
            //}
        }


        SalesTable locSalesTable=SalesTable::find(_salesId);
        ttsbegin;
        salesLine.clear();
        salesLine.initFromSalesTable(locSalesTable);
        salesLine.ItemId=_itemId;
        salesLine.initFromInventTable(inventTable::find(salesLine.ItemId));
        if (_inventDimId)
        {   // set product dimensions
            InventDim locInventDim=salesLine.inventDim();
            EcoResProductDimGroupSetup::copyProductDimensionsForItem(salesLine.ItemId, InventDim::find(_inventDimId), locInventDim);                
            salesLine.InventDimId=Inventdim::findOrCreate(locInventDim).inventDimId;                
        }
        salesLine.SalesQty=_salesQty;  
        salesLine.salesUnit=_salesUnit;
        salesLine.AVARUMCashVoucher=this.parmCashSalesDesk().CashVoucher;
        salesLine.SalesDeliverNow=_salesQty;
        salesLine.createLine(true,false,false,true,true,true);
        ttscommit;

        result = true;                                                               
    }
    catch
    {
        result = false;
    }

    return result;
}

