/// <summary>
/// Closes the cash desk
/// </summary>
/// <param name = "_cashSalesDesk">the AVARUMCashSalesDesk record </param>
public static void closeCashDesk(AVARUMCashSalesDesk _cashSalesDesk)
{        
    SalesLine locSalesLine;
    select firstonly locSalesLine 
        where locSalesLine.SalesId==_cashSalesDesk.salesid;

    ttsbegin;
    if (!locSalesLine)
    {   // no actions, cancel sales order
        SalesTable locSalesTable=SalesTable::find(_cashSalesDesk.salesid, true);
        if (locSalesTable)
        {
            locSalesTable.SalesStatus=SalesStatus::Canceled;
            locSalesTable.update();
        }
    }
    AVARUMCashSalesDeskBalance locAVARUMCashSalesDeskBalance;
    locAVARUMCashSalesDeskBalance.clear();
    locAVARUMCashSalesDeskBalance.initValue();
    locAVARUMCashSalesDeskBalance.OpenAmount=_cashSalesDesk.Amount;
    locAVARUMCashSalesDeskBalance.CloseAmount=_cashSalesDesk.CloseAmount;
    locAVARUMCashSalesDeskBalance.ClosedAt=_cashSalesDesk.ClosedAt;
    locAVARUMCashSalesDeskBalance.OpenAt=_cashSalesDesk.OpenAt;
    locAVARUMCashSalesDeskBalance.DeskId=_cashSalesDesk.Id;                
    locAVARUMCashSalesDeskBalance.SalesId=_cashSalesDesk.SalesId;
    locAVARUMCashSalesDeskBalance.insert();

    AVARUMCashSalesDesk updAVARUMCashSalesDesk;
    updAVARUMCashSalesDesk=AVARUMCashSalesDesk::findByRecId(_cashSalesDesk.RecId, true);
    updAVARUMCashSalesDesk.SalesId='';
    updAVARUMCashSalesDesk.CashVoucher='';
    updAVARUMCashSalesDesk.CloseAmount=0;
    updAVARUMCashSalesDesk.Amount=0;
    updAVARUMCashSalesDesk.update();
    ttscommit;    
}

/// <summary>
/// Post a cash voucher
/// </summary>
/// <param name = "_cashSalesDesk">the AVARUMCashSalesDesk record </param>
/// <param name = "_manager">Manger to work with </param>
public static void postCashDesk(AVARUMCashSalesDesk _cashSalesDesk, AVARUMCashSalesDeskManager _manager)
{
    SalesLine locSalesLine;
    SalesTotals totals;
    SalesAmount toalAmount;
    TaxAmount totalTax;        
    AmountCur totalBalance;        
    SalesTable locSalesTable=SalesTable::find(_cashSalesDesk.SalesId);

    totals = SalesTotals::construct(locSalesTable, SalesUpdate::DeliverNow);
    totals.calc();
    totalBalance = conPeek(totals.displayFields(), TradeTotals::posBalance());        
    totalTax = conPeek(totals.displayFields(), TradeTotals::posTaxTotal());
    toalAmount = conPeek(totals.displayFields(), TradeTotals::posTotalAmount());

    ttsbegin;
    update_recordset locSalesLine
        setting SalesDeliverNow=0
        where locSalesLine.SalesId==_cashSalesDesk.SalesId
        && locSalesLine.AVARUMCashVoucher==_cashSalesDesk.CashVoucher;



    AVARUMCashSalesCashVoucher locAVARUMCashSalesCashVoucher;
    locAVARUMCashSalesCashVoucher.clear();
    locAVARUMCashSalesCashVoucher.initValue();
    locAVARUMCashSalesCashVoucher.CashVoucher=_cashSalesDesk.CashVoucher;
    locAVARUMCashSalesCashVoucher.CashSalesDeskId=_cashSalesDesk.Id;
    locAVARUMCashSalesCashVoucher.GrossAmount=toalAmount;
    locAVARUMCashSalesCashVoucher.NetAmount=totalBalance;
    locAVARUMCashSalesCashVoucher.AmountMST=totalTax;
    locAVARUMCashSalesCashVoucher.AmountBack=_manager.getGivenAmount()-toalAmount;
    locAVARUMCashSalesCashVoucher.AmountGiven=_manager.getGivenAmount();
    locAVARUMCashSalesCashVoucher.insert();

    NumberSequenceReference numberSeqReference=NumberSeqReference::findReference(extendedTypeNum(AVARUMCashVoucher));
    NumberSeq NumberSeq=NumberSeq::newGetNum(numberSeqReference);
    AVARUMCashVoucher cashVoucher=NumberSeq.num();
    NumberSeq.used();

    AVARUMCashSalesDesk updAVARUMCashSalesDesk;
    updAVARUMCashSalesDesk=AVARUMCashSalesDesk::findByRecId(_cashSalesDesk.RecId, true);
    updAVARUMCashSalesDesk.CashVoucher=cashVoucher;
    updAVARUMCashSalesDesk.update();
    ttscommit;

    // whs relase
    salesTable salesTable=salesTable::find(_cashSalesDesk.SalesId);
    CustCreditMaxCheck creditMaxCheck = WHSParameters::getCreditMaxCheck();
    WHSWarehouseRelease::salesFormRelease(salesTable, creditMaxCheck);

    AVARUMCashSalesDeskManager::printCashInvoiceReport(locAVARUMCashSalesCashVoucher);

}

/// <summary>
/// N.Freidenberger 27.02.2026
/// </summary>
/// <param name = "_cashSalesCashVoucher"></param>
public static  void printCashInvoiceReport(AVARUMCashSalesCashVoucher       _cashSalesCashVoucher)
{
    Args            args = new Args();
    args.record(_cashSalesCashVoucher);

    AVARUMCashInvoiceController::main(args);
}

static private boolean checkCanClose(AVARUMCashSalesDesk _cashSalesDesk)
{
    SalesLine locSalesLine;

    select firstonly locSalesLine
        where locSalesLine.SalesDeliverNow>0
        && locSalesLine.SalesId==_cashSalesDesk.SalesId;

    if (locSalesLine)
    {
        throw error("@AVARUM:AVARUMCashSalesDeskManagerMsg1");
    }

    return true;
}
